export const IL_ADLARI = Object.fromEntries(IL_VERISI.split(";").map((s) => { const [k, ad] = s.split("|"); return [Number(k), ad]; }));
export const VERGI_DAIRELERI = VD_VERISI.split(";").map((s) => {
    const [kod, ad, ilce] = s.split("|");
    const ilKodu = Number(kod.slice(0, 3));
    return { kod, ad, ilKodu, il: IL_ADLARI[ilKodu] ?? "", ilce };
});
